\draw[->]  (Cara2) to node[above,align=center] 
{$\lenergy{D}{x,y}(\gamma) < \infty \implies \gamma \textnormal{ simple}$} 
node[below,align=center] {(\Cref{thm:finite-energy-is-simple})} (Hausdorff);
\node[squarednode]  (Hausdorff2) [below=of Cara2]  {\begin{tabular}{c} Hausdorff metric, \\
finite time (\Cref{thm:LDP-compact}) \end{tabular}};
\node[squarednode]  (Param) [below=of Hausdorff]  {\begin{tabular}{c} Parameterized curves, \\
finite time (\Cref{thm:radial-LDP-finite}) \end{tabular}};
\draw[->]  (Hausdorff2) to node[above,align=center] {\begin{tabular}{c} Exponential tightness \\ (\Cref{thm:exponential-tightness})\end{tabular}} node[below,align=center] {\begin{tabular}{c} Inverse contraction principle \\ (\Cref{thm:contraction-principle}\ref{item:Inverse_contraction_principle})\end{tabular}} (Param); 
\node[squarednode]  (Param2) [below=of Hausdorff2]  {\begin{tabular}{c} Parameterized curves, \\
finite time (\Cref{thm:radial-LDP-finite}) \end{tabular}};
\node[squarednode]  (Proj) [below=of Param]  {\begin{tabular}{c} Projective limit \\
(\Cref{thm:projective-LDP}) \end{tabular}};
\draw[->]  (Param2) to node[above,align=center] {Dawson-G\"artner theorem} node[below,align=center] {(\Cref{thm:Dawson-Gartner})} (Proj);
\node[squarednode]  (Proj2) [below=of Param2]  {\begin{tabular}{c} Projective limit \\
(\Cref{thm:projective-LDP}) \end{tabular}};
\node[squarednode]  (Main) [below=of Proj]  {\begin{tabular}{c} Full parameterized curves, \\
\Cref{thm:radial-LDP} \end{tabular}};
\draw[->]  (Proj2) to node[above,align=center] {Return estimates} node[below,align=center] {(\Cref{thm:return-estimates})} (Main);
\end{tikzpicture}
\end{center}
\caption{The proof of \Cref{thm:radial-LDP}.
The right column concerns different LDPs.}
